using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools that wrap the Open-Meteo weather REST API.
/// The MCP SDK discovers tools by scanning for [McpServerToolType] on the class
/// and [McpServerTool] on public methods. Constructor parameters are resolved via DI.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _http;

    // The SDK resolves constructor args from the DI container.
    // Because we register a named HttpClient, the framework injects it here.
    public WeatherTools(HttpClient http)
    {
        _http = http;
    }

    [McpServerTool, Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true";

        var response = await _http.GetFromJsonAsync<WeatherResponse>(url);
        if (response?.CurrentWeather is null)
            return "Unable to fetch weather data.";

        var w = response.CurrentWeather;
        return $"Temperature: {w.Temperature}°C, Wind: {w.WindSpeed} km/h, Direction: {w.WindDirection}°";
    }

    [McpServerTool, Description("Get a multi-day weather forecast for a location.")]
    public async Task<string> GetForecast(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        [Description("Number of forecast days (1-7)")] int days = 3)
    {
        days = Math.Clamp(days, 1, 7);
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}" +
                  $"&daily=temperature_2m_max,temperature_2m_min&forecast_days={days}";

        var response = await _http.GetFromJsonAsync<ForecastResponse>(url);
        if (response?.Daily is null)
            return "Unable to fetch forecast data.";

        var lines = new List<string>();
        for (int i = 0; i < response.Daily.Time.Count; i++)
        {
            lines.Add($"{response.Daily.Time[i]}: High {response.Daily.TemperatureMax[i]}°C, Low {response.Daily.TemperatureMin[i]}°C");
        }
        return string.Join("\n", lines);
    }
}

// DTOs for the Open-Meteo API
public record WeatherResponse(
    [property: JsonPropertyName("current_weather")] CurrentWeather? CurrentWeather);

public record CurrentWeather(
    [property: JsonPropertyName("temperature")] double Temperature,
    [property: JsonPropertyName("windspeed")] double WindSpeed,
    [property: JsonPropertyName("winddirection")] double WindDirection);

public record ForecastResponse(
    [property: JsonPropertyName("daily")] DailyForecast? Daily);

public record DailyForecast(
    [property: JsonPropertyName("time")] List<string> Time,
    [property: JsonPropertyName("temperature_2m_max")] List<double> TemperatureMax,
    [property: JsonPropertyName("temperature_2m_min")] List<double> TemperatureMin);

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using McpServer;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

// Register a typed HttpClient that the SDK will inject into WeatherTools
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.DefaultRequestHeaders.Add("User-Agent", "McpWeatherServer/1.0");
});

await builder.Build().RunAsync();

